1: import type {
2:     Color,
3:     ExtractionOptions,
4:     ImageSource,
5:     PixelData,
6:     PixelLoader,
7:     ProgressiveResult,
8:     Quantizer,
9:     SwatchMap,
10: } from './types.js';
11: import { validateOptions, extractPalette } from './pipeline.js';
12: import { extractProgressive } from './progressive.js';
13: import { classifySwatches } from './swatches.js';
14: import { MmcqQuantizer } from './quantizers/mmcq.js';
15: import { resolveDefaultLoader } from './resolve-loader.js';
16: 
17: // ---------------------------------------------------------------------------
18: // Global configuration
19: // ---------------------------------------------------------------------------
20: 
21: let globalLoader: PixelLoader<ImageSource> | null = null;
22: let globalQuantizer: Quantizer | null = null;
23: 
24: /**
25:  * Override the default pixel loader and/or quantizer.
26:  *
27:  * ```ts
28:  * import { configure } from 'colorthief';
29:  * import { WasmQuantizer } from 'colorthief/internals';
30:  * const q = new WasmQuantizer();
31:  * await q.init();
32:  * configure({ quantizer: q });
33:  * ```
34:  */
35: export function configure(opts: {
36:     loader?: PixelLoader<ImageSource>;
37:     quantizer?: Quantizer;
38: }): void {
39:     if (opts.loader) globalLoader = opts.loader;
40:     if (opts.quantizer) globalQuantizer = opts.quantizer;
41: }
42: 
43: // ---------------------------------------------------------------------------
44: // Lazy environment detection
45: // ---------------------------------------------------------------------------
46: 
47: async function getLoader(perCall?: PixelLoader<ImageSource>): Promise<PixelLoader<ImageSource>> {
48:     if (perCall) return perCall;
49:     if (globalLoader) return globalLoader;
50:     globalLoader = await resolveDefaultLoader();
51:     return globalLoader;
52: }
53: 
54: async function getQuantizer(perCall?: Quantizer): Promise<Quantizer> {
55:     if (perCall) {
56:         await perCall.init();
57:         return perCall;
58:     }
59:     if (globalQuantizer) return globalQuantizer;
60:     const q = new MmcqQuantizer();
61:     await q.init();
62:     globalQuantizer = q;
63:     return q;
64: }
65: 
66: // ---------------------------------------------------------------------------
67: // Helpers
68: // ---------------------------------------------------------------------------
69: 
70: function checkAborted(signal?: AbortSignal): void {
71:     if (signal?.aborted) {
72:         throw signal.reason ?? new DOMException('Aborted', 'AbortError');
73:     }
74: }
75: 
76: async function loadPixels(
77:     source: ImageSource,
78:     options?: ExtractionOptions,
79: ): Promise<PixelData> {
80:     checkAborted(options?.signal);
81:     const loader = await getLoader(options?.loader);
82:     return loader.load(source, options?.signal, options?.gamut ?? 'srgb');
83: }
84: 
85: // ---------------------------------------------------------------------------
86: // Public API
87: // ---------------------------------------------------------------------------
88: 
89: /**
90:  * Get the single dominant color from an image.
91:  *
92:  * ```ts
93:  * const color = await getColor(imgElement);
94:  * console.log(color.hex()); // '#e84393'
95:  * ```
96:  */
97: export async function getColor(
98:     source: ImageSource,
99:     options?: ExtractionOptions,
100: ): Promise<Color | null> {
101:     const palette = await getPalette(source, {
102:         colorCount: 5,
103:         ...options,
104:     });
105:     return palette ? palette[0] : null;
106: }
107: 
108: /**
109:  * Get a color palette from an image.
110:  *
111:  * ```ts
112:  * const palette = await getPalette(imgElement, { colorCount: 5 });
113:  * palette.forEach(c => console.log(c.hex()));
114:  * ```
115:  */
116: export async function getPalette(
117:     source: ImageSource,
118:     options?: ExtractionOptions,
119: ): Promise<Color[] | null> {
120:     const opts = validateOptions(options ?? {});
121: 
122:     checkAborted(options?.signal);
123: 
124:     // Worker path (browser only)
125:     if (options?.worker) {
126:         const { isWorkerSupported, extractInWorker } = await import(
127:             './worker/manager.js'
128:         );
129:         if (isWorkerSupported()) {
130:             const pixels = await loadPixels(source, options);
131:             const { createPixelArray, resolveOutputGamut } = await import('./pipeline.js');
132:             const pixelArray = createPixelArray(pixels.data, pixels.width * pixels.height, opts.quality, {
133:                 ignoreWhite: opts.ignoreWhite,
134:                 whiteThreshold: opts.whiteThreshold,
135:                 alphaThreshold: opts.alphaThreshold,
136:                 minSaturation: opts.minSaturation,
137:             });
138:             const nativeGamut = pixels.colorSpace ?? 'srgb';
139:             const outputGamut = resolveOutputGamut(pixelArray, nativeGamut, opts.gamut);
140:             return extractInWorker(
141:                 pixelArray,
142:                 opts.colorCount,
143:                 options?.signal,
144:                 nativeGamut,
145:                 outputGamut,
146:             );
147:         }
148:         // Fall through to main thread if workers not supported
149:     }
150: 
151:     const [pixels, quantizer] = await Promise.all([
152:         loadPixels(source, options),
153:         getQuantizer(options?.quantizer),
154:     ]);
155: 
156:     checkAborted(options?.signal);
157: 
158:     return extractPalette(
159:         pixels.data,
160:         pixels.width,
161:         pixels.height,
162:         opts,
163:         quantizer,
164:         pixels.colorSpace ?? 'srgb',
165:     );
166: }
167: 
168: /**
169:  * Get semantic swatches (Vibrant, Muted, etc.) from an image.
170:  *
171:  * ```ts
172:  * const swatches = await getSwatches(imgElement);
173:  * console.log(swatches.Vibrant?.color.hex());
174:  * ```
175:  */
176: export async function getSwatches(
177:     source: ImageSource,
178:     options?: ExtractionOptions,
179: ): Promise<SwatchMap> {
180:     const palette = await getPalette(source, {
181:         colorCount: 16,
182:         ...options,
183:     });
184:     return classifySwatches(palette ?? []);
185: }
186: 
187: /**
188:  * Progressively extract a palette with increasing quality.
189:  * Yields intermediate results so the UI can update incrementally.
190:  *
191:  * ```ts
192:  * for await (const { palette, progress, done } of getPaletteProgressive(img)) {
193:  *   updateUI(palette, progress);
194:  * }
195:  * ```
196:  */
197: export async function* getPaletteProgressive(
198:     source: ImageSource,
199:     options?: ExtractionOptions,
200: ): AsyncGenerator<ProgressiveResult> {
201:     const opts = validateOptions(options ?? {});
202: 
203:     const [pixels, quantizer] = await Promise.all([
204:         loadPixels(source, options),
205:         getQuantizer(options?.quantizer),
206:     ]);
207: 
208:     yield* extractProgressive(
209:         pixels.data,
210:         pixels.width,
211:         pixels.height,
212:         opts,
213:         quantizer,
214:         options?.signal,
215:         pixels.colorSpace ?? 'srgb',
216:     );
217: }

