3: // ---------------------------------------------------------------------------
4: // Constants (match original quantize library)
5: // ---------------------------------------------------------------------------
6: 
7: const SIGBITS = 5;
8: const RSHIFT = 8 - SIGBITS;
9: const MAX_ITERATIONS = 1000;
10: const FRACT_BY_POPULATIONS = 0.75;
11: const HISTO_SIZE = 1 << (3 * SIGBITS);
12: 
13: // ---------------------------------------------------------------------------
14: // Helpers
15: // ---------------------------------------------------------------------------
16: 
17: function getColorIndex(r: number, g: number, b: number): number {
18:     return (r << (2 * SIGBITS)) + (g << SIGBITS) + b;
19: }
