137: class PQueue<T> {
138:     private contents: T[] = [];
139:     private sorted = false;
140: 
141:     constructor(private comparator: (a: T, b: T) => number) {}
142: 
143:     private sort(): void {
144:         this.contents.sort(this.comparator);
145:         this.sorted = true;
146:     }
147: 
148:     push(item: T): void {
149:         this.contents.push(item);
150:         this.sorted = false;
151:     }
152: 
153:     peek(index?: number): T {
154:         if (!this.sorted) this.sort();
155:         return this.contents[index ?? this.contents.length - 1];
156:     }
157: 
