            const totalPopulation = raw.reduce((sum: number, q: { population: number }) => sum + q.population, 0);
            const colors = raw.map(({ color, population }) => {
                const [r, g, b] =
                    nativeGamut === outputGamut ? color : p3ToSrgb(color[0], color[1], color[2]);
