35:     if (typeof colorCount === 'undefined' || !Number.isInteger(colorCount)) {
36:         colorCount = 10;
37:     } else if (colorCount === 1) {
38:         throw new Error(
39:             'colorCount should be between 2 and 20. To get one color, call getColor() instead of getPalette()',
40:         );
