42:         colorCount = Math.max(colorCount, 2);
43:         colorCount = Math.min(colorCount, 20);
44:     }
45: 
46:     if (
47:         typeof quality === 'undefined' ||
48:         !Number.isInteger(quality) ||
49:         quality < 1
50:     ) {
51:         quality = 10;
52:     }
53: 
54:     const ignoreWhite =
