58:     const alphaThreshold =
59:         typeof options.alphaThreshold === 'number' ? options.alphaThreshold : 125;
60:     const minSaturation =
61:         typeof options.minSaturation === 'number'
62:             ? Math.max(0, Math.min(1, options.minSaturation))
63:             : 0;
64:     const colorSpace = options.colorSpace ?? 'oklch';
65:     const gamut = options.gamut ?? 'srgb';
66: 
67:     return {
68:         colorCount,
69:         quality,
70:         ignoreWhite,
71:         whiteThreshold,
72:         alphaThreshold,
