118:         whiteThreshold = 250,
119:         alphaThreshold = 125,
120:         minSaturation = 0,
121:     } = filterOptions;
122: 
123:     const pixelArray: Array<[number, number, number]> = [];
124: 
125:     for (let i = 0; i < pixelCount; i += quality) {
126:         const offset = i * 4;
127:         const r = data[offset];
128:         const g = data[offset + 1];
129:         const b = data[offset + 2];
130:         const a = data[offset + 3];
