export function readViaCanvas(
    width: number,
    height: number,
    gamut: Gamut | 'auto',
    draw: (ctx: CanvasRenderingContext2D) => void,
): PixelData {
    const colorSpace = effectiveColorSpace(gamut);
    const canvas = document.createElement('canvas');
    canvas.width = width;
    canvas.height = height;
    const ctx = (
