4: // ---------------------------------------------------------------------------
5: // OKLCH target ranges for each swatch role
6: // ---------------------------------------------------------------------------
7: 
8: interface SwatchTarget {
9:     role: SwatchRole;
10:     /** Target OKLCH lightness (0–1). */
11:     targetL: number;
12:     /** Min / max lightness. */
13:     minL: number;
14:     maxL: number;
15:     /** Target chroma (0–0.4). */
16:     targetC: number;
17:     /** Min chroma. */
18:     minC: number;
19: }
20: 
21: const TARGETS: SwatchTarget[] = [
22:     { role: 'Vibrant',      targetL: 0.65, minL: 0.40, maxL: 0.85, targetC: 0.20, minC: 0.08 },
23:     { role: 'Muted',        targetL: 0.65, minL: 0.40, maxL: 0.85, targetC: 0.04, minC: 0.00 },
24:     { role: 'DarkVibrant',  targetL: 0.30, minL: 0.00, maxL: 0.45, targetC: 0.20, minC: 0.08 },
25:     { role: 'DarkMuted',    targetL: 0.30, minL: 0.00, maxL: 0.45, targetC: 0.04, minC: 0.00 },
26:     { role: 'LightVibrant', targetL: 0.85, minL: 0.70, maxL: 1.00, targetC: 0.20, minC: 0.08 },
27:     { role: 'LightMuted',   targetL: 0.85, minL: 0.70, maxL: 1.00, targetC: 0.04, minC: 0.00 },
28: ];
29: 
30: // ---------------------------------------------------------------------------
31: // Scoring
32: // ---------------------------------------------------------------------------
33: 
34: const WEIGHT_L = 6;
35: const WEIGHT_C = 3;
36: const WEIGHT_POP = 1;
37: 
38: function score(
39:     color: Color,
40:     target: SwatchTarget,
41:     maxPopulation: number,
42: ): number {
43:     const { l, c } = color.oklch();
44: 
45:     // Out of lightness range → disqualified
46:     if (l < target.minL || l > target.maxL) return -Infinity;
47:     // Below minimum chroma → disqualified
48:     if (c < target.minC) return -Infinity;
49: 
50:     const lDist = 1 - Math.abs(l - target.targetL);
51:     const cDist = 1 - Math.min(Math.abs(c - target.targetC) / 0.2, 1);
52:     const pop = maxPopulation > 0 ? color.population / maxPopulation : 0;
53: 
54:     return lDist * WEIGHT_L + cDist * WEIGHT_C + pop * WEIGHT_POP;
55: }
