71: /**
72:  * Classify a palette into semantic swatch roles using OKLCH distance scoring.
73:  * Each role is matched to the best-scoring palette color. A color can only
74:  * be assigned to one role (the one where it scores highest).
75:  */
76: export function classifySwatches(palette: Color[]): SwatchMap {
77:     const maxPopulation = Math.max(...palette.map((c) => c.population), 1);
78: 
79:     // Score every (color, target) pair
80:     const assignments: Array<{
81:         role: SwatchRole;
82:         color: Color;
83:         score: number;
84:     }> = [];
85: 
86:     for (const target of TARGETS) {
87:         let bestColor: Color | null = null;
88:         let bestScore = -Infinity;
89: 
90:         for (const color of palette) {
91:             const s = score(color, target, maxPopulation);
92:             if (s > bestScore) {
93:                 bestScore = s;
