14: // 3D Color Histogram
15: // ---------------------------------------------------------------------------
16: 
17: fn color_index(r: u32, g: u32, b: u32) -> usize {
18:     ((r << (2 * SIGBITS)) + (g << SIGBITS) + b) as usize
19: }
20: 
21: fn build_histogram(pixels: &[u8]) -> (Vec<u32>, usize) {
22:     let mut hist = vec![0u32; HIST_SIZE];
23:     let num_pixels = pixels.len() / 3;
24: 
25:     for i in 0..num_pixels {
26:         let r = (pixels[i * 3] as u32) >> RSHIFT;
27:         let g = (pixels[i * 3 + 1] as u32) >> RSHIFT;
28:         let b = (pixels[i * 3 + 2] as u32) >> RSHIFT;
29:         hist[color_index(r, g, b)] += 1;
30:     }
31: 
32:     (hist, num_pixels)
33: }
