35: // ---------------------------------------------------------------------------
36: // VBox — a box in 5-bit quantized RGB space
37: // ---------------------------------------------------------------------------
38: 
39: #[derive(Clone)]
40: struct VBox {
41:     r_min: u32,
42:     r_max: u32,
43:     g_min: u32,
44:     g_max: u32,
45:     b_min: u32,
46:     b_max: u32,
47:     count: u32,
48:     volume: u32,
49: }
50: 
51: impl VBox {
52:     fn from_pixels(pixels: &[u8]) -> Self {
53:         let mut r_min = 255u32;
54:         let mut r_max = 0u32;
55:         let mut g_min = 255u32;
56:         let mut g_max = 0u32;
57:         let mut b_min = 255u32;
58:         let mut b_max = 0u32;
59: 
60:         let num_pixels = pixels.len() / 3;
61:         for i in 0..num_pixels {
62:             let r = (pixels[i * 3] as u32) >> RSHIFT;
63:             let g = (pixels[i * 3 + 1] as u32) >> RSHIFT;
64:             let b = (pixels[i * 3 + 2] as u32) >> RSHIFT;
65:             r_min = r_min.min(r);
66:             r_max = r_max.max(r);
67:             g_min = g_min.min(g);
68:             g_max = g_max.max(g);
69:             b_min = b_min.min(b);
70:             b_max = b_max.max(b);
71:         }
72: 
73:         VBox {
74:             r_min, r_max, g_min, g_max, b_min, b_max,
75:             count: 0,
76:             volume: 0,
77:         }
78:     }
79: 
80:     fn update_count(&mut self, hist: &[u32]) {
81:         let mut count = 0u32;
82:         for r in self.r_min..=self.r_max {
83:             for g in self.g_min..=self.g_max {
84:                 for b in self.b_min..=self.b_max {
85:                     count += hist[color_index(r, g, b)];
86:                 }
87:             }
88:         }
89:         self.count = count;
90:     }
91: 
92:     fn update_volume(&mut self) {
93:         self.volume = (self.r_max - self.r_min + 1)
94:             * (self.g_max - self.g_min + 1)
95:             * (self.b_max - self.b_min + 1);
96:     }
97: 
98:     fn avg_color(&self, hist: &[u32]) -> (u8, u8, u8, u32) {
99:         let mut r_sum = 0u64;
100:         let mut g_sum = 0u64;
101:         let mut b_sum = 0u64;
102:         let mut total = 0u64;
103: 
104:         for r in self.r_min..=self.r_max {
105:             for g in self.g_min..=self.g_max {
106:                 for b in self.b_min..=self.b_max {
107:                     let h = hist[color_index(r, g, b)] as u64;
108:                     if h > 0 {
109:                         total += h;
110:                         r_sum += h * ((r << RSHIFT) + (1 << (RSHIFT - 1))) as u64;
111:                         g_sum += h * ((g << RSHIFT) + (1 << (RSHIFT - 1))) as u64;
112:                         b_sum += h * ((b << RSHIFT) + (1 << (RSHIFT - 1))) as u64;
113:                     }
114:                 }
115:             }
116:         }
117: 
118:         if total == 0 {
119:             let r = ((self.r_min + self.r_max + 1) << RSHIFT) / 2;
120:             let g = ((self.g_min + self.g_max + 1) << RSHIFT) / 2;
121:             let b = ((self.b_min + self.b_max + 1) << RSHIFT) / 2;
122:             return (r.min(255) as u8, g.min(255) as u8, b.min(255) as u8, 0);
123:         }
124: 
125:         (
126:             (r_sum / total).min(255) as u8,
127:             (g_sum / total).min(255) as u8,
128:             (b_sum / total).min(255) as u8,
129:             total as u32,
130:         )
131:     }
