133:     fn widest_dimension(&self) -> u8 {
134:         let r_range = self.r_max - self.r_min;
135:         let g_range = self.g_max - self.g_min;
136:         let b_range = self.b_max - self.b_min;
137:         if r_range >= g_range && r_range >= b_range { 0 }
138:         else if g_range >= r_range && g_range >= b_range { 1 }
139:         else { 2 }
