147: fn median_cut(hist: &[u32], vbox: &VBox) -> Option<(VBox, VBox)> {
148:     if vbox.count <= 1 {
149:         return None;
150:     }
151: 
152:     let dim = vbox.widest_dimension();
153: 
154:     // Build partial sums along the widest dimension
155:     let (range_min, range_max) = match dim {
156:         0 => (vbox.r_min, vbox.r_max),
157:         1 => (vbox.g_min, vbox.g_max),
158:         _ => (vbox.b_min, vbox.b_max),
159:     };
160: 
161:     if range_min == range_max {
162:         return None;
163:     }
164: 
165:     let mut partial_sum = vec![0i64; (range_max + 1) as usize];
166:     let mut total = 0i64;
167: 
168:     for i in range_min..=range_max {
169:         let mut sum = 0i64;
170:         match dim {
171:             0 => {
172:                 for g in vbox.g_min..=vbox.g_max {
173:                     for b in vbox.b_min..=vbox.b_max {
174:                         sum += hist[color_index(i, g, b)] as i64;
175:                     }
176:                 }
177:             }
178:             1 => {
179:                 for r in vbox.r_min..=vbox.r_max {
180:                     for b in vbox.b_min..=vbox.b_max {
181:                         sum += hist[color_index(r, i, b)] as i64;
182:                     }
183:                 }
184:             }
185:             _ => {
186:                 for r in vbox.r_min..=vbox.r_max {
187:                     for g in vbox.g_min..=vbox.g_max {
188:                         sum += hist[color_index(r, g, i)] as i64;
189:                     }
190:                 }
191:             }
192:         }
193:         total += sum;
194:         partial_sum[i as usize] = total;
195:     }
196: 
197:     // Find the split point
198:     for i in range_min..=range_max {
199:         if partial_sum[i as usize] > total / 2 {
200:             let left = i - range_min;
201:             let right = range_max - i;
202:             let cut = if left <= right {
203:                 (i + right / 2).min(range_max - 1)
204:             } else {
205:                 (i - 1 - left / 2).max(range_min)
206:             };
207: 
208:             let mut vbox1 = vbox.clone();
209:             let mut vbox2 = vbox.clone();
210: 
211:             match dim {
212:                 0 => { vbox1.r_max = cut; vbox2.r_min = cut + 1; }
213:                 1 => { vbox1.g_max = cut; vbox2.g_min = cut + 1; }
214:                 _ => { vbox1.b_max = cut; vbox2.b_min = cut + 1; }
215:             }
216: 
217:             vbox1.update_count(hist);
218:             vbox1.update_volume();
219:             vbox2.update_count(hist);
220:             vbox2.update_volume();
221: 
222:             return Some((vbox1, vbox2));
223:         }
224:     }
225: 
226:     None
227: }
