230: // Priority queue (sort by comparator, split largest)
231: // ---------------------------------------------------------------------------
232: 
233: fn iterate(
234:     queue: &mut Vec<VBox>,
235:     hist: &[u32],
236:     target: usize,
237:     compare_by_product: bool,
238: ) {
239:     let mut n_iters = 0;
240: 
241:     loop {
242:         if compare_by_product {
243:             queue.sort_by(|a, b| {
244:                 let pa = (a.count as u64) * (a.volume as u64);
245:                 let pb = (b.count as u64) * (b.volume as u64);
246:                 pa.cmp(&pb)
247:             });
248:         } else {
249:             queue.sort_by(|a, b| a.count.cmp(&b.count));
250:         }
